import sys

# 威佐夫博弈 (Wythoff's game): 必败态 = (floor(k*phi), floor(k*phi^2)), phi=(1+sqrt5)/2
PHI = (1 + 5 ** 0.5) / 2


def is_losing(a, b):
    """判断局面 (a,b) 是否为先手必败态。输入顺序无关。"""
    if a > b:
        a, b = b, a
    k = b - a
    x = int(k * PHI)  # floor(k*phi)
    return x == a and x + k == b


def solve(a, b):
    if is_losing(a, b):
        return "LOSE"
    # 枚举全部合法着法, 取字典序最小 (先 i 后 j) 的必胜着法
    for i in range(0, a + 1):
        for j in range(0, b + 1):
            if i == 0 and j == 0:
                continue
            # 合法着法: 只动一堆, 或同时取相同数目的石子
            if i > 0 and j > 0 and i != j:
                continue
            if is_losing(a - i, b - j):
                return "WIN %d %d" % (i, j)
    return "LOSE"  # 理论上不可达


def solve_str(line):
    """按行解析两个整数并返回该行结果, 兼容空行/多余空白。"""
    data = line.split()
    if len(data) < 2:
        return None
    a, b = int(data[0]), int(data[1])
    return solve(a, b)


def selftest():
    """自测入口: 每例一行 PASS/FAIL, 结尾一行总判定, 返回进程退出码。"""
    cases = [
        ("1 2", "LOSE"),
        ("2 1", "LOSE"),
        ("3 5", "LOSE"),
        ("1 1", "WIN 1 1"),
        ("4 7", "LOSE"),
        ("0 0", "LOSE"),
        ("5 3", "LOSE"),
        ("2 2", "WIN 1 1"),
    ]
    ok = True
    for line, expect in cases:
        got = solve_str(line)
        status = "PASS" if got == expect else "FAIL"
        if got != expect:
            ok = False
        print("%s: %s -> %s (expect %s)" % (status, line, got, expect))
    print("TOTAL: %s" % ("PASS" if ok else "FAIL"))
    return 0 if ok else 1


def main():
    argv = sys.argv[1:]
    if "--selftest" in argv:
        sys.exit(selftest())
    data = sys.stdin.read().split()
    if len(data) < 2:
        return
    a, b = int(data[0]), int(data[1])
    sys.stdout.write(solve(a, b) + "\n")


if __name__ == "__main__":
    main()
